"""Conversation context compaction for multi-turn browser tasks.

Historically the frontend flattened the whole thread into one string and the
backend prepended up to 12k characters of it to the agent task. That made old,
unrelated results compete with the current instruction and let the agent drift
to objects or actions mentioned earlier in the conversation.

This module keeps the same idea (older turns must be remembered) but splits it
into two parts:

* a compact rolling summary of older turns, generated by the active LLM, and
* the last few turns verbatim, because follow-ups usually refer to them.

The current user request is always appended separately and marked as the only
goal to execute.
"""

from __future__ import annotations

import logging

from pydantic import BaseModel, Field

from browser_use.llm.messages import SystemMessage, UserMessage

logger = logging.getLogger('browser_buddy.context')

# Only spend an extra LLM call once the rendered history exceeds this size.
CONTEXT_CHAR_BUDGET = 6000
# Turns kept verbatim next to the summary. Two exchanges are usually enough to
# resolve "继续", "这个", "上面那个".
RECENT_TURN_COUNT = 4
PER_TURN_CHAR_LIMIT = 2000
SUMMARY_CHAR_LIMIT = 1600
SUMMARY_INPUT_LIMIT = 12000

# thread_id -> (number_of_turns_already_summarized, summary)
_SUMMARY_CACHE: dict[str, tuple[int, str]] = {}


class ContextTurn(BaseModel):
	"""A minimal chat turn sent by the frontend for context building."""

	role: str
	text: str = ''
	links: list[str] = Field(default_factory=list)
	files: list[str] = Field(default_factory=list)


def clear_thread_summary(thread_id: str) -> None:
	"""Drop a cached summary after the thread is edited or deleted."""
	_SUMMARY_CACHE.pop(thread_id, None)


def _normalize(messages: list[ContextTurn] | None) -> list[ContextTurn]:
	turns: list[ContextTurn] = []
	for message in messages or []:
		if message.role not in ('user', 'assistant'):
			continue
		text = (message.text or '').strip()
		if not text and not message.links and not message.files:
			continue
		turns.append(message)
	return turns


def _render_turn(turn: ContextTurn) -> str:
	role = '用户' if turn.role == 'user' else '助手'
	text = (turn.text or '').strip()
	if len(text) > PER_TURN_CHAR_LIMIT:
		text = text[:PER_TURN_CHAR_LIMIT] + '…'
	parts = [f'{role}：{text}' if text else f'{role}：']
	if turn.links:
		parts.append(f'链接：{", ".join(turn.links[:8])}')
	if turn.files:
		parts.append(f'文件：{", ".join(turn.files[:8])}')
	return '\n'.join(parts)


def _render_turns(turns: list[ContextTurn]) -> str:
	return '\n\n'.join(_render_turn(turn) for turn in turns)


def _fallback_summary(turns: list[ContextTurn]) -> str:
	"""Deterministic fallback when the summary LLM call fails."""
	rendered = _render_turns(turns[-6:])
	return rendered[-SUMMARY_CHAR_LIMIT:]


async def _summarize(llm, turns: list[ContextTurn], thread_id: str | None) -> str:
	if not turns:
		return ''

	covered = len(turns)
	previous_summary = ''
	new_turns = turns

	if thread_id:
		cached = _SUMMARY_CACHE.get(thread_id)
		if cached is not None:
			cached_covered, cached_summary = cached
			if 0 < cached_covered <= covered:
				previous_summary = cached_summary
				new_turns = turns[cached_covered:]

	if not new_turns:
		return previous_summary

	history = _render_turns(new_turns)[-SUMMARY_INPUT_LIMIT:]
	if previous_summary:
		prompt = (
			'下面是一段多轮对话的已有摘要，以及新增的对话内容。'
			'请输出合并后的新摘要，不要解释过程。\n\n'
			f'已有摘要：\n{previous_summary[:SUMMARY_CHAR_LIMIT]}\n\n'
			f'新增对话：\n{history}'
		)
	else:
		prompt = f'请把下面这段多轮对话压缩成一份上下文摘要。\n\n{history}'

	system = (
		'你负责为浏览器自动化助手压缩对话上下文。'
		'必须保留：用户提到的具体对象、商品、型号、数量、筛选条件、网站、已确认的结论、'
		'关键链接和文件名。删除寒暄、重复内容和浏览器执行细节。'
		'不要编造没有出现过的信息。用中文输出不超过 600 字的要点列表。'
	)

	summary = ''
	try:
		response = await llm.ainvoke([SystemMessage(content=system), UserMessage(content=prompt)])
		summary = str(getattr(response, 'completion', '') or '').strip()
	except Exception as e:
		logger.warning(f'Context summarization failed: {type(e).__name__}: {e}')

	if not summary:
		summary = _fallback_summary(new_turns)
		if previous_summary:
			summary = f'{previous_summary}\n{summary}'[-SUMMARY_CHAR_LIMIT:]
	else:
		summary = summary[:SUMMARY_CHAR_LIMIT]

	if thread_id:
		_SUMMARY_CACHE[thread_id] = (covered, summary)
	return summary


async def build_conversation_context(
	llm,
	messages: list[ContextTurn] | None,
	thread_id: str | None = None,
) -> tuple[str, str]:
	"""Return ``(summary_of_older_turns, recent_turns_verbatim)``.

	Small threads skip the summary entirely, so the common case still costs
	exactly zero extra LLM calls.
	"""
	turns = _normalize(messages)
	if not turns:
		return '', ''

	rendered = [_render_turn(turn) for turn in turns]
	total_chars = sum(len(item) for item in rendered) + 2 * len(rendered)

	if total_chars <= CONTEXT_CHAR_BUDGET:
		return '', '\n\n'.join(rendered)

	split = max(0, len(turns) - RECENT_TURN_COUNT)
	older = turns[:split]
	recent = turns[split:]
	summary = await _summarize(llm, older, thread_id) if older else ''
	recent_text = _render_turns(recent)[-CONTEXT_CHAR_BUDGET:]
	return summary, recent_text
